insert into public.config_item (uid, category, default_value, description, key, name, super_admin_edit, user_parent_config, value_type) select replace(uuid_generate_v4()::text,'-',''), 5, 'false', '到货清单合同号和验收材料是否必填', 'enableArrivalListRequired', '到货清单必填项', 'f', 't', 3 where not exists (select * from config_item where key = 'enableArrivalListRequired');